def served_model_id():
    """The id under which the notebook's vLLM server serves the model (falls back to the model path)."""
    import urllib.request
    try:
        with urllib.request.urlopen('http://127.0.0.1:8000/v1/models', timeout=10) as r:
            return json.load(r)['data'][0]['id']
    except Exception as e:
        print('could not query /v1/models:', repr(e), flush=True)
        return MODEL_PATH


def model_registry():
    if os.environ.get('NO_LLM'):
        return ModelRegistry()
    cfg = VllmConfig(model=MODEL_PATH, port=8000, host='127.0.0.1', tool_call_parser='gemma4', reasoning_parser='gemma4',
                     default_chat_template_kwargs={'enable_thinking': True}, max_model_len=32768,
                     tensor_parallel_size=4)
    served = served_model_id()
    print('served model id', served, flush=True)
    return VllmServer(cfg).create_model_registry(aliases={TARGET: served}, model_prefix='openai/', api_key='EMPTY')


def make_evaluator(arm, worker, models, budget):
    limits, gen = build_submission_limits()
    cfg = EvalConfig(
        tasks_path=DATA / 'tasks.jsonl', snapshots_dir=DATA / 'snapshots',
        results_dir=E2E / 'results' / arm / f'w{worker}',
        submission_dir=E2E / 'agents' / ('base' if arm == 'gold' else arm), models=models, sandbox='subprocess',
        timeout_seconds=budget['timeout_seconds'], max_time_minutes=budget['max_time_minutes'],
        max_tool_calls=budget['max_tool_calls'], max_turns=budget['max_turns'],
        limits=limits, generation_constraints=gen, adapter_manifest=None,
        context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
        # the values of the competition's scoring script (HARNESS_README section 7.2)
        events_compaction_config=EventsCompactionConfig(compaction_interval=5, overlap_size=2, token_threshold=14336,
                                                        event_retention_size=5),
        graph_dir=str(DATA / 'graphs'), embeddings_dir=str(DATA / 'embeddings'), wheels_dir=DATA / 'wheels',
        verbose=False, display_mode='quiet')
    return Evaluator(cfg)


def done_jobs():
    done = set()
    for p in glob.glob(str(E2E / 'records' / '*.jsonl')):
        for line in open(p):
            try:
                r = json.loads(line)
            except ValueError:
