import json, os, shutil, sys

DATA = '/kaggle/input/competitions/gemma-4-developer-agent'
E2E = os.environ.get('E2E', '/kaggle/working/e2e')
BUDGET = json.load(open(f'{E2E}/budget.json'))

SAMPLING = """temperature: 0.2
top_p: 0.95
max_output_tokens: 16384
thinking_config:
  thinking_budget: 4096
  include_thoughts: true
"""
TOOLS = ['run_command', 'read_file', 'edit_file', 'write_file', 'get_status', 'submit_patch',
         'get_code_neighbors', 'search_similar_code', 'get_code_subgraph']
STEP0 = """### 0. Localize First with the `graph-localize` Skill
- Your first action: call `run_skill_script` with `skill_name="graph-localize"`, `file_path="scripts/localize.py"` and `args={"issue": "<key sentences, identifiers, file names and error messages from the problem statement>", "k": 15}`.
- It prints the 15 functions, methods and classes most likely to need a change as `rank score path:line qualified.name`. Read the top candidates with `read_file` starting at the printed line, then continue with the workflow below.
- If the top candidates do not fit, read further down the list before searching elsewhere. The graph tools do not know async functions.

"""
ANCHOR = '### 1. Identify Target Files Immediately'


def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        f.write(text)


def build(arm):
    d = f'{E2E}/agents/{arm}'
    shutil.rmtree(d, ignore_errors=True)
    system = open(f'{DATA}/sample_submission/prompts/system.md').read()
    if arm == 'skill':
        assert system.count(ANCHOR) == 1
        system = system.replace(ANCHOR, STEP0 + ANCHOR)
        for rel in ('SKILL.md', 'scripts/localize.py'):
            write(f'{d}/skills/graph-localize/{rel}', open(f'{E2E}/skill_src/{rel}').read())
    write(f'{d}/prompts/system.md', system)
    write(f'{d}/configs/sampling.yaml', SAMPLING)
    agent = ['name: swe_agent', 'model: gemma-4-31b-it-qat-w4a16-ct', 'instruction: !include prompts/system.md', 'tools:']
    agent += [f'  - {t}' for t in TOOLS]
    if arm == 'skill':
        agent += ['skills:', '  - skills/graph-localize']
    agent += ['generate_content_config: !include configs/sampling.yaml']
    write(f'{d}/agent.yaml', '\n'.join(agent) + '\n')
    write(f'{d}/eval_config.yaml', 'evaluation:\n' + ''.join(f'  {k}: {v}\n' for k, v in BUDGET.items()))
    return d


if __name__ == '__main__':
